  'auto.firewallProviders.15x6sol': 'if command -v ufw >/dev/null 2>&1; then printf \'{value0}\\tufw\\n\' if command -v sudo >/dev/null 2>&1 && sudo -n true >/dev/null 2>&1; then sudo -n ufw status numbered verbose 2>/dev/null || sudo -n ufw status numbered 2>/dev/null || sudo -n ufw status verbose 2>/dev/null || sudo -n ufw status 2>/dev/null else ufw status numbered verbose 2>/dev/null || ufw status numbered 2>/dev/null || ufw status verbose 2>/dev/null || ufw status 2>/dev/null fi printf \'{value1}\\n\' if command -v sudo >/dev/null 2>&1 && sudo -n true >/dev/null 2>&1; then sudo -n ufw show added 2>/dev/null || true else ufw show added 2>/dev/null || true fi exit 0\nfi\nif command -v firewall-cmd >/dev/null 2>&1; then printf \'{value2}\\tfirewalld\\n\' printf \'{value3}\\n\' state=$(sudo -n firewall-cmd --state 2>/dev/null || firewall-cmd --state 2>&1 || printf unknown) printf \'%s\\n\' "$state" zone=$(sudo -n firewall-cmd --get-default-zone 2>/dev/null || firewall-cmd --get-default-zone 2>/dev/null || sudo -n firewall-cmd --permanent --get-default-zone 2>/dev/null || firewall-cmd --permanent --get-default-zone 2>/dev/null || printf public) printf \'{value4}\\t%s\\n\' "$zone" printf \'{value5}\\n\' if printf \'%s\' "$state" | grep -qi \'^running$\'; then sudo -n firewall-cmd --list-all --zone="$zone" 2>&1 || firewall-cmd --list-all --zone="$zone" 2>&1 || sudo -n firewall-cmd --permanent --list-all --zone="$zone" 2>&1 || firewall-cmd --permanent --list-all --zone="$zone" 2>&1 else sudo -n firewall-cmd --permanent --list-all --zone="$zone" 2>&1 || firewall-cmd --permanent --list-all --zone="$zone" 2>&1 || sudo -n firewall-cmd --list-all --zone="$zone" 2>&1 || firewall-cmd --list-all --zone="$zone" 2>&1 fi exit 0\nfi\nprintf \'{value6}\\tunknown\\n\'\nprintf \'ufw or firewalld was not detected.\\n\'',
