  'auto.remoteNetworkDiagnostics.14pspjf': 'if command -v tracepath >/dev/null 2>&1; then tracepath {value0}; elif command -v traceroute >/dev/null 2>&1; then traceroute {value1}; else echo \'tracepath or traceroute is missing.\' >&2; exit 127; fi',
  'auto.remoteNetworkDiagnostics.mnmkjd': '$watch = [System.Diagnostics.Stopwatch]::StartNew()\ntry { $response = Invoke-WebRequest -Uri {value0} -Method Head -MaximumRedirection 5 -TimeoutSec {value1} -UseBasicParsing $watch.Stop() [Console]::Out.WriteLine("HTTP $($response.StatusCode) $($response.StatusDescription)") [Console]::Out.WriteLine("Elapsed $($watch.ElapsedMilliseconds) ms") $response.Headers.GetEnumerator() | Sort-Object Key | ForEach-Object { [Console]::Out.WriteLine("$($_.Key): $($_.Value)") }\n} catch { $watch.Stop() [Console]::Out.WriteLine("Elapsed $($watch.ElapsedMilliseconds) ms") throw\n}',
