  'auto.remoteServiceManager.15rk3jd': 'Masked',
  'auto.remoteServiceManager.1lpnuh42': 'Unknown',
  'auto.remoteServiceManager.ftv1bn': 'if ! command -v systemctl >/dev/null 2>&1; then printf \'{value0}systemctl is not installed or the current PATH is unavailable.\\n\' exit 0\nfi\nprintf \'{value1}\\n\'\nsystemctl list-units --type=service --all --no-pager --plain --no-legend 2>/dev/null | awk \'BEGIN{OFS="\\t"} NF >= 4 { unit=$1; load=$2; active=$3; sub=$4; desc=""; for (i=5; i<=NF; i++) desc=desc (i>5?" ":"") $i; print unit, load, active, sub, desc }\'\nprintf \'{value2}\\n\'\nsystemctl list-unit-files --type=service --no-pager --plain --no-legend 2>/dev/null | awk \'BEGIN{OFS="\\t"} NF >= 2 { print $1, $2 }\'',
  'auto.remoteServiceManager.tz62dt': '\nif ! command -v systemctl >/dev/null 2>&1; then\n  printf \'{value0}systemctl is not installed or current PATH is unavailable.\\n\'\n  exit 127\nfi\nprintf \'{value1}\\n\'\nsystemctl show {value2} --no-pager -p Id -p Description -p LoadState -p ActiveState -p SubState -p UnitFileState -p MainPID -p MemoryCurrent -p FragmentPath -p ActiveEnterTimestamp -p ExecMainStartTimestamp 2>&1 || true\nprintf \'{value3}\\n\'\nsystemctl status {value4} --no-pager --lines=80 2>&1 || true\nprintf \'{value5}\\n\'\nif command -v journalctl >/dev/null 2>&1; then\n  journalctl -u {value6} -n 100 --no-pager --output=short-iso 2>&1 || true\nelse\n  printf \'journalctl is unavailable.\\n\'\nfi\nprintf \'{value7}\\n\'\nsystemctl cat {value8} --no-pager 2>&1 || true\n',
  'auto.remoteServiceManager.1jxcuyv': 'if ! command -v systemctl >/dev/null 2>&1; then printf \'systemctl is not installed or the current PATH is unavailable.\\n\' exit 127\nfi\nif [ "$(id -u 2>/dev/null)" = "0" ]; then systemctl {value0} {value1} 2>&1\nelif command -v sudo >/dev/null 2>&1 && sudo -n true 2>/dev/null; then sudo -n systemctl {value2} {value3} 2>&1\nelse systemctl {value4} {value5} 2>&1\nfi',
  'auto.remoteServiceManager.1lwtgdd': '\n$serviceName = {value0}\n$service = Get-CimInstance Win32_Service -ErrorAction Stop | Where-Object { $_.Name -eq $serviceName } | Select-Object -First 1\nif (-not $service) { throw "Service does not exist: $serviceName" }\n$detail = [pscustomobject]@{\n  name = [string]$service.Name\n  displayName = [string]$service.DisplayName\n  description = [string]$service.Description\n  status = [string]$service.State\n  startType = [string]$service.StartMode\n  pid = if ($null -ne $service.ProcessId -and [int]$service.ProcessId -gt 0) { [int]$service.ProcessId } else { $null }\n  pathName = [string]$service.PathName\n  serviceType = [string]$service.ServiceType\n  startName = [string]$service.StartName\n  exitCode = [string]$service.ExitCode\n  serviceSpecificExitCode = [string]$service.ServiceSpecificExitCode\n}\n"{value1}"\n$detail | ConvertTo-Json -Compress -Depth 4\n"{value2}"\n$detail | Format-List | Out-String\n"{value3}"\ntry {\n  $displayName = [string]$service.DisplayName\n  $events = Get-WinEvent -FilterHashtable @{ LogName = \'System\'; ProviderName = \'Service Control Manager\'; StartTime = (Get-Date).AddDays(-14) } -MaxEvents 240 -ErrorAction SilentlyContinue |\n    Where-Object { $_.Message -like "*$serviceName*" -or (-not [string]::IsNullOrWhiteSpace($displayName) -and $_.Message -like "*$displayName*") } |\n    Select-Object -First 100\n  if ($events) {\n    $events | ForEach-Object {\n      $message = ($_.Message -replace "\\s+", " ").Trim()\n      "{0:u} [{1}] {2}" -f $_.TimeCreated, $_.LevelDisplayName, $message\n    }\n  } else {\n    "No recent Service Control Manager events found."\n  }\n} catch {\n  "Unable to read system event log: $($_.Exception.Message)"\n}\n"{value4}"\n"Name: $($service.Name)"\n"DisplayName: $($service.DisplayName)"\n"StartMode: $($service.StartMode)"\n"StartName: $($service.StartName)"\n"PathName: $($service.PathName)"\n"ServiceType: $($service.ServiceType)"\n',
